class LFUCache(Cache):
    """LFU Cache implementation
    It works based on the LFU (Least Frequently Used) cache algorithm,
    which means that the most rarely used items are removed from the
    cache before adding a new item.
    """
    def __init__(self, maxsize, typed):
        super().__init__(maxsize, typed)
        count = collections.Counter()

    def get(self, *args, **kwargs):
        access_time = count[args]
        if access_time == maxsize:
            if kwargs:
                del self.data[args][list(kwargs)]
            else:
                del self.data[args]
        count[args] += 1
        if args in self.data:
            if kwargs:
                return self.data[args].get(kwargs)
            else:
                return self.data[args]
        else:
            if kwargs:
                self.data[args] = {kwargs: value}
                return value
            else:
                self.data[args] = value
                return value

    def clear(self):
        super().clear()
        self.count.clear()

