    seen = set()
    ordered = []
    for cls in classes:
        if cls not in seen:
            trace = [cls]
            while trace:
                cls = trace.pop()
                if cls in seen:
                    continue
                seen.add(cls)
                trace.extend(b for b in cls.__bases__ if b not in trace)
            ordered.append(cls)
    return ordered

