    """
    bases = set(classes)
    for i in range(len(bases)-1,0,-1):
        base = bases[i]
        for j in range(i-1,-1,-1):
            other = bases[j]
            if issubclass(other, base):
                bases.remove(base)
                break
    return list(bases)

