def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple):
        raise TypeError("Coordinates must be a tuple of length 2")
    if len(coord) != 2:
        raise ValueError("Coordinates must be a tuple of length 2")
    if not isinstance(weight, int) and not isinstance(weight, float):
        raise TypeError("Weight must be an integer or a float")

    x, y = coord
    if x < 0 or x >= self.nbins_x:
        return
    if y < 0 or y >= self.nbins_y:
        return

    bin_x = int(x * self.bins_x)
    bin_y = int(y * self.bins_y)
    self.histogram[bin_y][bin_x] += weight

    return self

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.bins[0] or coord > self.bins[-1]:
        return
    idx = bisect.bisect_left(self.edges, coord)
    self.counts[idx] += weight
    self.sum += weight * coord
    self.sum_squares += weight * coord ** 2
    if self.nan_policy == 'omit':
        self.nan_count += weight * math.isnan(coord)
    elif self.nan_policy == 'propagate':
        self.nan_count += weight * math.isnan(coord) * 1
    else:
        raise ValueError('invalid nan_policy: {!r}'.format(self.nan_policy))
    if self.inf_policy == 'omit':
        self.inf_count += weight * math.isinf(coord)
    elif self.inf_policy == 'propagate':
        self.inf_count += weight * math.isinf(coord) * 1
    else:
        raise ValueError('invalid inf_policy: {!r}'.format(self.inf_policy))

