                    continue

            # Check the digest if requested
            if check_digests and obj.digest:
                try:
                    if obj.digest.check():
                        good_objects += 1
                    else:
                        if show_warnings:
                            print(f"Digest invalid for {obj}")
                except DigestError as e:
                    if show_warnings:
                        print(f"Digest error for {obj}: {e}")

    # Return the counts
    return num_objects, good_objects

