def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.startswith("0"):
        # version is a zero-prefixed version
        version = version[1:]
        version = str(int(version) + 1)
        return "0" + version
    else:
        return str(int(version) + 1)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    is_zero_prefixed = version.startswith('0')
    parts = version.split('.')
    next_parts = []
    for part in parts:
        if is_zero_prefixed:
            if part[0] == '0':
                # increment the digit inside the zero prefix
                next_parts.append(str(int(part[1:]) + 1))
            else:
                # remove the zero prefix
                next_parts.append(part[1:])
        else:
            # increment the last digit
            next_parts.append(str(int(part) + 1))
    return '.'.join(next_parts)

