def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    version_inventories = [self._get_directory(version_dir) for version_dir in version_dirs]
    root_inventory = self._get_directory('inventory')

    content_digests = {}
    for version_inventory in version_inventories:
        version = int(version_inventory.name)
        root_digests = [note.digest for note in root_inventory.notes if note.version == version]

        versions_inventory = set(note.version for note in version_inventory.notes)
        for note in version_inventory.notes:
            if note.version not in versions_inventory:
                yield (f"{version_inventory}/{note.block_label}.md", "orphan")

        for note in version_inventory.notes:
            if note.digest not in root_digests and note.version == version:
                content_digests[note.digest] = True

    for digest in content_digests:
        yield ("", "inconsistent-content-digests", digest)

