def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if os.path.isdir(path) and path.endswith("ocfl_object"):
        return 'object'
    if os.path.isdir(path) and path.endswith("ocfl_root"):
        return 'root'
    if os.path.isdir(path) and path.endswith("file"):
        return 'file'
    if os.path.isfile(path) and path.endswith("occ"):
        return 'file'
    if os.path.isfile(path) and path.endswith("jsonld"):
        return 'file'
    if os.path.isfile(path) and path.endswith("nt"):
        return 'file'
    if os.path.isfile(path) and path.endswith("meta"):
        return 'file'
    if os.path.isfile(path) and path.endswith("txt"):
        return 'file'
    return 'unknown'

