def vertex3tuple(vertices):
    """
    Given a list of vertices, return a list of tuples of 3 points for each vertex. Each tuple will include the original vertex and the 2 points on both sides of the vertex.

    Example:
    given a polygon with vertices ABCD, will return DAB, ABC, BCD, CDA. This function returns 3 tuples.
