def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    match = re.match(r"^(\d+)\s*(seconds?|minutes?|hours?|days?|weeks?|months?|years?)$", frequency.lower())
    if not match:
        raise ValueError(f"Unable to parse frequency: {frequency}")
    amount, unit = match.groups()
    amount = int(amount)
    unit_map = {"seconds": 1, "minutes": 60, "hours": 3600, "days": 86400, "weeks": 604800, "months": 2629800, "years": 31557600}
    return datetime.timedelta(seconds=amount * unit_map[unit])

