    netloc = parsed_href.netloc
    scheme = parsed_href.scheme

    image_id = None
    use_ssl = False

    if scheme == 'https':
        use_ssl = True
    elif scheme == 'http':
        use_ssl = False
    else:
        raise ValueError(f'Unsupported scheme: {scheme}')

