        netloc = netloc[2:]

    if netloc:
        netloc_parts = netloc.split('.')
        if netloc_parts[0] == 'img':
            image_id = '.'.join(netloc_parts[1:])

        else:
            raise ValueError(f'Unsupported netloc: {netloc}')

    return image_id, netloc, use_ssl

