def find_tags(text: str, replacer: callable = None) -> Tuple[Set[str], str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code_block = False
    for i, c in enumerate(text):
        if c == '`':
            if in_code_block:
                in_code_block = False
            else:
                in_code_block = True
        elif not in_code_block and c in '<>':
            # Find the closing tag
            j = i
            while j < len(text) - 1 and text[j + 1] != c:
                j += 1
            if j < len(text) - 1:
                tag = text[i: j + 2]
                tags.add(tag)
                if replacer:
                    text = text.replace(tag, replacer(tag))
    return tags, text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    orig_text = text
    text = text.replace('<', '|<').replace('>', '>|')
    text = re.sub(r'``(.+?)``', r'||\1|', text)
    text = re.sub(r'`([^`]+)`', r'||\1|', text)
    for match in re.finditer(r'<(\w+)[^>]*>', text):
        tag = match.group(1)
        tags.add(tag)
        if replacer:
            orig_text = orig_text.replace(match.group(), replacer(match.group()))
    return tags, orig_text.replace('|<', '<').replace('>|', '>')

