    """
    open_tags = set()
    closed_tags = set()
    new_text = ""
    for tag in get_tags(text):
        if tag.lstrip("#").lower() in closed_tags:
            closed_tags.remove(tag.lstrip("#").lower())
        else:
            open_tags.add(tag)

    for char in text:
        if char == '`':
            continue
        if open_tags and char == '>':
            open_tags.remove(open_tags.pop())
        if closed_tags and char == '<':
            closed_tags.add(closed_tags.pop())
        if open_tags:
            new_text += char

    if replacer is not None:
        for tag in closed_tags:
            new_text = new_text.replace(tag, replacer(tag))

    return (closed_tags, new_text)
