def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    if method == "post":
        response = requests.post(url, data, timeout=timeout, *args, **kwargs)
    elif method == "get":
        response = requests.get(url, data, timeout=timeout, *args, **kwargs)
    else:
        raise ValueError("Invalid method: {0}. Valid methods are 'post' and 'get'".format(method))

    try:
        response.raise_for_status()
    except requests.exceptions.HTTPError as err:
        return response.status_code, err.args[0]

    return response.status_code, None

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional *args and **kwargs will be passed on to requests.post.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        response = requests.request(method, url, data, timeout=timeout, *args, **kwargs)
        status_code = response.status_code
        if status_code >= 200 and status_code < 300:
            return status_code, None
        else:
            return status_code, response.raise_for_status()
    except Exception as e:
        return None, e

def list_of_file_names(settings_dirs, spec_option):
    """
    Create a new list of file names based on the settings directories and the specification option.

    Args:
        settings_dirs (list of str): The list of settings directories to gather the file names from.
        spec_option (str): The specification option to use for gathering the file names.

    Returns:
        list of str: The list of file names.
    """

    file_names = []
    for settings_dir in settings_dirs:
        for root, dirs, files in os.walk(settings_dir):
            for file in files:
                if spec_option in file:
                    file_names.append(os.path.join(root, file))

    return file_names

